import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { QueryClientProvider } from '@tanstack/react-query';
import { Toaster } from 'sonner';
import { App } from './App';
import { createQueryClient } from './lib/query';
import { AuthProvider } from './lib/auth';
import { ThemeProvider } from './lib/theme';
import { ErrorBoundary } from './components/ErrorBoundary';
import { LanguageRoot } from './i18n/LanguageRoot';
import { reloadForNewVersion } from './lib/chunk-reload';
import './index.css';
import { demoRibbonState } from './lib/demo-ribbon';

// Vite fires this when a screen's file from an older deploy is gone.
window.addEventListener('vite:preloadError', (event) => {
  event.preventDefault();
  reloadForNewVersion();
});

/** Demo ribbon: thin, dismissible, reserves exactly its own height so it
 *  never covers app controls (0 once dismissed; dismissal resets on reload). */
function DemoRibbon(): React.JSX.Element {
  const ref = React.useRef<HTMLDivElement>(null);
  const dismissed = React.useSyncExternalStore(demoRibbonState.sub, demoRibbonState.get);
  const setDismissed = demoRibbonState.set;
  React.useEffect(() => {
    const set = (): void => {
      const h = !dismissed && ref.current ? Math.ceil(ref.current.getBoundingClientRect().height) : 0;
      document.documentElement.style.setProperty('--demo-ribbon-h', `${h}px`);
    };
    set();
    window.addEventListener('resize', set);
    return () => window.removeEventListener('resize', set);
  }, [dismissed]);
  return (
    <>
      <style>{`
        #root { padding-bottom: var(--demo-ribbon-h, 22px); }
        body nav.fixed.bottom-0 { bottom: var(--demo-ribbon-h, 22px) !important; }
        body aside.fixed { bottom: var(--demo-ribbon-h, 22px) !important; }
        a[aria-label="Create a new trip"] { bottom: calc(72px + var(--demo-ribbon-h, 22px)) !important; }
        body [role="dialog"] .sticky.bottom-0 { bottom: var(--demo-ribbon-h, 22px) !important; }
        .demo-ribbon { position: fixed; bottom: 0; left: 0; right: 0; z-index: 9999; background: #b91c1c; color: #fff; font-size: 11px; line-height: 1.3; padding: 2px 8px calc(2px + env(safe-area-inset-bottom, 0px)); font-weight: 600; display: flex; align-items: center; justify-content: center; gap: 6px; padding-right: 46px; }
        .demo-ribbon button { position: absolute; right: 2px; top: 50%; transform: translateY(-50%); width: 44px; height: 44px; background: none; border: none; color: #fff; font-size: 14px; line-height: 1; cursor: pointer; }
      `}</style>
      {dismissed ? null : (
        <div ref={ref} className="demo-ribbon" role="note">
          <span>DEMO - invented sample data; edits reset on reload; nothing real is sent.</span>
          <button type="button" aria-label="Hide demo banner" onClick={() => setDismissed(true)}>&#10005;</button>
        </div>
      )}
    </>
  );
}

const queryClient = createQueryClient();

/**
 * Register the service worker.
 *
 * In the old app a <PushNotificationSetup> component existed but was never
 * mounted, so no service worker was ever registered — and since a push
 * subscription requires one, "enable notifications" hung forever with no error.
 * Registration happens here, at startup, for every visitor.
 */
if ('serviceWorker' in navigator && import.meta.env.VITE_DEMO_MODE !== 'true') {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/service-worker.js').catch((error: unknown) => {
      // Offline support and push are enhancements; the app runs without them.
      console.warn('Service worker registration failed', error);
    });
  });
}

const root = document.getElementById('root');
if (!root) throw new Error('Missing #root element');

ReactDOM.createRoot(root).render(
  <React.StrictMode>
    <ErrorBoundary>
      <QueryClientProvider client={queryClient}>
        <ThemeProvider>
          <BrowserRouter basename={import.meta.env.BASE_URL}>
            <AuthProvider>
              <LanguageRoot>
                <App />
                <Toaster richColors position="top-center" closeButton />
                {import.meta.env.VITE_DEMO_MODE === 'true' ? <DemoRibbon /> : null}
              </LanguageRoot>
            </AuthProvider>
          </BrowserRouter>
        </ThemeProvider>
      </QueryClientProvider>
    </ErrorBoundary>
  </React.StrictMode>,
);
