import { DEMO_MODE } from '../lib/demo';
import { demoUnitPhoto } from '../lib/demo/equipment';
/**
 * Equipment: the stock list grouped by type, barcode scanning, and what is
 * out on loan.
 *
 * A loan is a row with a lifecycle (loan → return), which is what the API
 * models, so this screen never edits fields on the item to fake a loan.
 * Retired units stay on file forever but out of the way: they appear only
 * when "Include out-of-service units" is ticked, and their counts live in
 * Reports.
 */
import React, { useMemo, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {Camera, History, Package, PackageCheck, Plus, ScanBarcode, Pencil} from 'lucide-react';
import { equipmentSchema, loanEquipmentSchema } from '@rvc/shared';
import { api, errorMessage } from '@/lib/api';
import { qk } from '@/lib/query';
import { formatDate, titleCase, formatPhone } from '@/lib/format';

/**
 * The date input yields `YYYY-MM-DD`. `new Date(that)` is UTC midnight — the
 * previous evening here — so loans showed the wrong due date and went
 * "overdue" the evening before. "Due back Oct 20" means the end of Oct 20
 * local time.
 */
function localEndOfDayIso(ymd: string): string {
  const [y, m, d] = ymd.split('-').map(Number) as [number, number, number];
  return new Date(y, m - 1, d, 23, 59, 59).toISOString();
}
import { useAuth } from '@/lib/auth';
import { Modal } from '@/components/Modal';
import { BarcodeScanner } from '@/components/BarcodeScanner';
import {
  EmptyState, ErrorState, ListSkeleton, PageHeader, cardClass, inputClass, labelClass, primaryButtonClass,
  secondaryButtonClass,
} from '@/components/states';
import type {
  EquipmentCategoriesResponse, EquipmentFeatures, EquipmentHistoryResponse, EquipmentLoansResponse,
  EquipmentResponse, EquipmentRow, EquipmentScanResponse,
} from '@/types/api';

const STATUS_CLASSES: Record<string, string> = {
  available: 'bg-green-100 text-green-700 dark:bg-green-500/15 dark:text-green-300',
  loaned: 'bg-blue-100 text-blue-700 dark:bg-blue-500/15 dark:text-blue-300',
  maintenance: 'bg-amber-100 text-amber-800 dark:bg-amber-500/15 dark:text-amber-300',
  retired: 'bg-slate-200 text-slate-700 dark:bg-slate-700 dark:text-slate-200',
};

const REASON_LABELS: Record<string, string> = {
  beyond_repair: 'Broken beyond repair',
  lost: 'Lost',
  worn_out: 'Worn out',
  other: 'Other',
};

function unitTitle(item: Pick<EquipmentRow, 'name' | 'equipmentType' | 'itemCode'>): string {
  return item.name?.trim() || titleCase(item.equipmentType) + (item.itemCode ? ` · ${item.itemCode}` : '');
}

function identityLine(item: EquipmentRow): string {
  return [item.brand, item.model, item.purchaseYear ? String(item.purchaseYear) : null].filter(Boolean).join(' · ');
}

function specEntries(features: EquipmentFeatures | null): Array<[string, string]> {
  if (!features) return [];
  return Object.entries(features)
    .filter(([, v]) => v !== null && v !== '' && v !== false)
    .map(([k, v]) => [k, v === true ? 'Yes' : String(v)]);
}

function UnitPhoto({ id, photoFileId, className }: { id: string; photoFileId?: string | null; className?: string }): React.JSX.Element {
  // ?v= keyed on the file id: after a reshoot the pointer (and URL) changes,
  // so nobody verifies identity against a cached photo of the old shot.
  return (
    <img
      src={DEMO_MODE ? demoUnitPhoto(id) : `/api/equipment/${id}/photo${photoFileId ? `?v=${photoFileId}` : ''}`}
      alt="Photo of the actual unit"
      className={className ?? 'h-28 w-full rounded-lg border border-slate-200 object-cover dark:border-slate-700'}
      loading="lazy"
    />
  );
}

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(new Error('read failed'));
    reader.readAsDataURL(file);
  });
}

export function EquipmentPage(): React.JSX.Element {
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const isDispatch = user?.role === 'dispatcher' || user?.role === 'admin';

  const [addOpen, setAddOpen] = useState(false);
  const [editing, setEditing] = useState<EquipmentRow | null>(null);
  const [loanFor, setLoanFor] = useState<EquipmentRow | null>(null);
  const [returnFor, setReturnFor] = useState<EquipmentRow | null>(null);
  const [historyFor, setHistoryFor] = useState<EquipmentRow | null>(null);
  const [issueFor, setIssueFor] = useState<EquipmentRow | null>(null);
  const [disposeFor, setDisposeFor] = useState<EquipmentRow | null>(null);
  const [scanOpen, setScanOpen] = useState(false);
  const [scanned, setScanned] = useState<EquipmentScanResponse | null>(null);
  const [manualCode, setManualCode] = useState('');
  const [expandedTypes, setExpandedTypes] = useState<Set<string>>(() => new Set());
  const photoInput = useRef<HTMLInputElement | null>(null);
  const [photoFor, setPhotoFor] = useState<EquipmentRow | null>(null);

  const equipment = useQuery({
    queryKey: qk.equipment.list({}),
    queryFn: () => api.get<EquipmentResponse>('/api/equipment', { limit: 500 }),
  });
  const categories = useQuery({
    queryKey: qk.equipment.categories(),
    queryFn: () => api.get<EquipmentCategoriesResponse>('/api/equipment/categories'),
  });
  const loans = useQuery({
    queryKey: qk.equipment.loans(true),
    queryFn: () => api.get<EquipmentLoansResponse>('/api/equipment/loans', { open: true }),
    enabled: isDispatch,
  });

  const invalidate = (): void => {
    void queryClient.invalidateQueries({ queryKey: ['equipment'] });
  };

  /** Stock grouped by equipment type, A-Z; retired units stay out of sight
   *  unless explicitly asked for. */
  const groups = useMemo(() => {
    const rows = equipment.data?.equipment ?? [];
    const byType = new Map<string, EquipmentRow[]>();
    for (const row of rows) {
      const key = row.equipmentType.trim().toLowerCase() || 'other';
      const list = byType.get(key) ?? [];
      list.push(row);
      byType.set(key, list);
    }
    return [...byType.entries()].sort(([a], [b]) => a.localeCompare(b));
  }, [equipment.data]);

  const lookupCode = useMutation({
    mutationFn: (code: string) => api.get<EquipmentScanResponse>(`/api/equipment/scan/${encodeURIComponent(code.trim())}`),
    onSuccess: (data) => {
      setScanned(data);
      setScanOpen(false);
      setManualCode('');
    },
    onError: (error: unknown) => toast.error(errorMessage(error)),
  });

  const uploadPhoto = useMutation({
    mutationFn: async ({ item, file }: { item: EquipmentRow; file: File }) => {
      const image = await fileToDataUrl(file);
      return api.post(`/api/equipment/${item.id}/photo`, { image });
    },
    onSuccess: () => {
      invalidate();
      toast.success('Photo saved.');
      setPhotoFor(null);
      setScanned(null);
    },
    onError: (error: unknown) => toast.error(errorMessage(error)),
  });

  return (
    <div className="space-y-6">
      <PageHeader
        title="Equipment"
        subtitle="Wheelchairs, walkers and everything else on loan"
        actions={
          isDispatch ? (
            <div className="flex flex-wrap gap-2">
              <button type="button" className={primaryButtonClass} onClick={() => setScanOpen(true)}>
                <ScanBarcode className="h-4 w-4" aria-hidden="true" />
                Scan
              </button>
              <button type="button" className={secondaryButtonClass} onClick={() => setAddOpen(true)}>
                <Plus className="h-4 w-4" aria-hidden="true" />
                Add item
              </button>
            </div>
          ) : undefined
        }
      />

      {isDispatch ? (
        <section className={`${cardClass} p-4`}>
          <h2 className="font-semibold text-slate-900 dark:text-white">Lend or return a unit</h2>
          <p className="mt-1 text-sm text-slate-600 dark:text-slate-400">Scan its sticker to check the unit and record a loan or return. Use the stock list below to check availability.</p>
          <button type="button" className={`${primaryButtonClass} mt-3 w-full sm:w-auto`} onClick={() => setScanOpen(true)}><ScanBarcode className="h-4 w-4" aria-hidden="true" /> Scan sticker</button>
        </section>
      ) : null}

      {isDispatch ? (
        <details className={`${cardClass} p-4`}>
          <summary className="cursor-pointer text-sm font-medium text-slate-700 dark:text-slate-300">Open loan records ({loans.data?.loans.length ?? 0})</summary>
          <div className="mt-3">
          {loans.isPending ? (
            <ListSkeleton rows={2} lines={1} />
          ) : loans.isError ? (
            <ErrorState error={loans.error} onRetry={() => void loans.refetch()} what="open loans" />
          ) : loans.data.loans.length === 0 ? (
            <EmptyState icon={PackageCheck} title="Nothing is out on loan." hint="Everything on the shelf is accounted for." />
          ) : (
            <ul className="space-y-2">
              {loans.data.loans.map((row) => {
                const overdue = row.expectedReturnAt ? new Date(row.expectedReturnAt).getTime() < Date.now() : false;
                return (
                  <li key={row.id} className={`${cardClass} flex flex-wrap items-center justify-between gap-3 p-4`}>
                    <div className="min-w-0">
                      <p className="font-medium text-slate-900 dark:text-white">
                        {titleCase(row.equipmentType)}
                        {row.itemCode ? ` · ${row.itemCode}` : ''}
                      </p>
                      <p className="text-sm text-slate-600 dark:text-slate-400">
                        {row.borrowerName} · {formatPhone(row.borrowerPhone)}
                      </p>
                      <p className={`text-xs ${overdue ? 'font-medium text-[#C80023]' : 'text-slate-500 dark:text-slate-400'}`}>
                        {row.expectedReturnAt ? `${overdue ? 'Overdue since' : 'Due back'} ${formatDate(row.expectedReturnAt)}` : 'No return date set'}
                      </p>
                    </div>
                    <button type="button" className={secondaryButtonClass} onClick={() => {
                      const item = (equipment.data?.equipment ?? []).find((r) => r.id === row.equipmentId);
                      setReturnFor(item ?? null);
                    }}>
                      Mark returned
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
          </div>
        </details>
      ) : null}

      <section>
        <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
          <h2 className="text-lg font-semibold text-slate-900 dark:text-white">Stock by type</h2>

        </div>
        {equipment.isPending ? (
          <ListSkeleton rows={4} lines={1} />
        ) : equipment.isError ? (
          <ErrorState error={equipment.error} onRetry={() => void equipment.refetch()} what="the equipment list" />
        ) : groups.length === 0 ? (
          <EmptyState icon={Package} title="No equipment has been catalogued yet." hint="Add wheelchairs, walkers and other loan items to track where they are." />
        ) : (
          <div className="space-y-6">
            {groups.map(([type, rows]) => {
              const available = rows.filter((row) => row.status === 'available');
              const other = rows.filter((row) => row.status !== 'available');
              const expanded = expandedTypes.has(type);
              const card = (row: EquipmentRow): React.JSX.Element => (
                <ItemCard key={row.id} row={row} isDispatch={isDispatch}
                  onLend={() => setLoanFor(row)} onReturn={() => setReturnFor(row)}
                  onHistory={() => setHistoryFor(row)} onIssue={() => setIssueFor(row)}
                  onDispose={() => setDisposeFor(row)} onEdit={() => setEditing(row)}
                  onPhoto={() => { setPhotoFor(row); photoInput.current?.click(); }} />
              );
              return (
                <div key={type} className={`${cardClass} p-4`}>
                  <h3>
                    <button type="button" className="flex min-h-[44px] w-full items-center justify-between gap-3 text-left font-semibold text-slate-900 dark:text-white"
                      aria-expanded={expanded} aria-controls={`stock-${type}`}
                      onClick={() => setExpandedTypes((previous) => { const next = new Set(previous); if (next.has(type)) next.delete(type); else next.add(type); return next; })}>
                      <span>{titleCase(rows[0]!.equipmentType)} - {available.length} available</span>
                      <span aria-hidden="true">{expanded ? '−' : '+'}</span>
                    </button>
                  </h3>
                  {expanded ? (
                    <div id={`stock-${type}`} className="mt-3 space-y-4">
                      {available.length ? <ul className="grid grid-cols-1 gap-3 sm:grid-cols-2">{available.map(card)}</ul> : <p className="text-sm text-slate-500">No units available right now.</p>}
                      {isDispatch && other.length ? (
                        <details>
                          <summary className="cursor-pointer text-xs text-slate-500 dark:text-slate-400">Other unit records ({other.length}): on loan, maintenance or out of service</summary>
                          <ul className="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-2">{other.map(card)}</ul>
                        </details>
                      ) : null}
                    </div>
                  ) : null}
                </div>
              );
            })}
          </div>
        )}
      </section>

      <input
        ref={photoInput}
        type="file"
        accept="image/*"
        capture="environment"
        className="hidden"
        aria-hidden="true"
        onChange={(event) => {
          const file = event.target.files?.[0];
          event.target.value = '';
          if (file && photoFor) uploadPhoto.mutate({ item: photoFor, file });
        }}
      />
      {/* Scan: camera when the device supports it, typed code always. */}
      <Modal open={scanOpen} title="Scan or type a code" onClose={() => setScanOpen(false)}>
        <div className="space-y-4">
          <BarcodeScanner onDetected={(code) => lookupCode.mutate(code)} />
          <form
            className="flex gap-2"
            onSubmit={(event) => {
              event.preventDefault();
              if (manualCode.trim()) lookupCode.mutate(manualCode);
            }}
          >
            <input
              className={inputClass}
              value={manualCode}
              onChange={(event) => setManualCode(event.target.value)}
              placeholder="RVCWCH7 or item code"
              aria-label="Barcode or item code"
            />
            <button type="submit" className={primaryButtonClass} disabled={lookupCode.isPending || !manualCode.trim()}>
              Look up
            </button>
          </form>
        </div>
      </Modal>

      {scanned ? (
        <ScanResultSheet
          data={scanned}
          isDispatch={isDispatch}
          onClose={() => setScanned(null)}
          onHistory={() => {
            setHistoryFor(scanned.item);
            setScanned(null);
          }}
          onIssue={() => {
            setIssueFor(scanned.item);
            setScanned(null);
          }}
          onLend={() => {
            setLoanFor(scanned.item);
            setScanned(null);
          }}
          onReturn={() => {
            setReturnFor(scanned.item);
            setScanned(null);
          }}
          onDispose={() => {
            setDisposeFor(scanned.item);
            setScanned(null);
          }}
          onEdit={() => {
            setEditing(scanned.item);
            setScanned(null);
          }}
          onPhoto={() => {
            setPhotoFor(scanned.item);
            photoInput.current?.click();
          }}
        />
      ) : null}

      <AddItemModal open={addOpen} onClose={() => setAddOpen(false)} categories={categories.data?.categories ?? []} onSaved={invalidate} />
      {editing ? <EditItemModal row={editing} categories={categories.data?.categories ?? []} onClose={() => setEditing(null)} onSaved={invalidate} /> : null}
      {loanFor ? <LendModal item={loanFor} onClose={() => setLoanFor(null)} onSaved={invalidate} /> : null}
      {returnFor ? <ReturnModal item={returnFor} onClose={() => setReturnFor(null)} onSaved={invalidate} /> : null}
      {historyFor ? <HistoryModal item={historyFor} onClose={() => setHistoryFor(null)} /> : null}
      {issueFor ? <IssueModal item={issueFor} onClose={() => setIssueFor(null)} onSaved={invalidate} /> : null}
      {disposeFor ? <DecommissionModal item={disposeFor} onClose={() => setDisposeFor(null)} onSaved={invalidate} /> : null}
    </div>
  );
}

function ItemCard({
  row, isDispatch, onLend, onReturn, onHistory, onIssue, onDispose, onPhoto, onEdit,
}: {
  row: EquipmentRow;
  isDispatch: boolean;
  onLend: () => void;
  onReturn: () => void;
  onHistory: () => void;
  onIssue: () => void;
  onDispose: () => void;
  onPhoto: () => void;
  onEdit: () => void;
}): React.JSX.Element {
  const specs = specEntries(row.features);
  return (
    <li className={`${cardClass} p-4`}>
      <div className="flex gap-3">
        {row.photoFileId ? <UnitPhoto id={row.id} photoFileId={row.photoFileId} className="h-20 w-20 shrink-0 rounded-lg border border-slate-200 object-cover dark:border-slate-700" /> : null}
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-start justify-between gap-2">
            <div className="min-w-0">
              <p className="font-medium text-slate-900 dark:text-white">{unitTitle(row)}</p>
              {identityLine(row) ? <p className="text-sm text-slate-600 dark:text-slate-400">{identityLine(row)}</p> : null}
              <p className="text-sm text-slate-600 dark:text-slate-400">
                {row.itemCode ?? 'No code'}
                {row.barcode ? ` · ${row.barcode}` : ''}
                {row.size ? ` · Size ${row.size}` : ''}
                {' · '}
                {titleCase(row.condition)}
              </p>
              {specs.length > 0 ? (
                <p className="text-xs text-slate-500 dark:text-slate-400">{specs.map(([k, v]) => `${titleCase(k)}: ${v}`).join(' · ')}</p>
              ) : null}
              {row.status === 'retired' ? (
                <p className="text-xs text-slate-500 dark:text-slate-400">
                  Out of service{row.retiredReason ? ` - ${REASON_LABELS[row.retiredReason] ?? row.retiredReason}` : ''}
                  {row.retiredAt ? `, ${formatDate(row.retiredAt)}` : ''}
                </p>
              ) : null}
              {row.notes ? <p className="text-xs text-slate-500 dark:text-slate-400">{row.notes}</p> : null}
            </div>
            <span className={`rounded-full px-3 py-1 text-xs font-medium ${STATUS_CLASSES[row.status] ?? STATUS_CLASSES.retired}`}>
              {titleCase(row.status)}
            </span>
          </div>
        </div>
      </div>
      {isDispatch ? (
        <div className="mt-3 flex flex-wrap gap-2">
          {row.status === 'available' ? (
            <button type="button" className={secondaryButtonClass} onClick={onLend}>
              Lend out
            </button>
          ) : null}
          {row.status === 'loaned' ? (
            <button type="button" className={secondaryButtonClass} onClick={onReturn}>
              Mark returned
            </button>
          ) : null}
          <button type="button" className={secondaryButtonClass} onClick={onHistory} aria-label={`History of ${unitTitle(row)}`}>
            <History className="h-4 w-4" aria-hidden="true" />
          </button>
          <button type="button" className={secondaryButtonClass} onClick={onPhoto} aria-label={`Photo of ${unitTitle(row)}`}>
            <Camera className="h-4 w-4" aria-hidden="true" />
          </button>
          <button type="button" className={secondaryButtonClass} onClick={onEdit} aria-label={`Edit ${unitTitle(row)}`}>
            <Pencil className="h-4 w-4" aria-hidden="true" />
          </button>
          {row.status !== 'retired' ? (
            <button type="button" className={secondaryButtonClass} onClick={onIssue}>
              Report issue
            </button>
          ) : null}
          {row.status === 'maintenance' || row.status === 'available' ? (
            <button type="button" className={secondaryButtonClass} onClick={onDispose}>
              Take out of service
            </button>
          ) : null}
        </div>
      ) : null}
    </li>
  );
}

/** The scan result: what the unit is, plus the four deliberate choices.
 *  Scanning itself changed nothing - every action below is a separate tap. */
function ScanResultSheet({
  data, isDispatch, onClose, onHistory, onIssue, onLend, onReturn, onDispose, onPhoto, onEdit,
}: {
  data: EquipmentScanResponse;
  isDispatch: boolean;
  onClose: () => void;
  onHistory: () => void;
  onIssue: () => void;
  onLend: () => void;
  onReturn: () => void;
  onDispose: () => void;
  onPhoto: () => void;
  onEdit: () => void;
}): React.JSX.Element {
  const item = data.item;
  const specs = specEntries(item.features);
  return (
    <Modal open title="Scanned unit" onClose={onClose}>
      <div className="space-y-4">
        {item.photoFileId ? (
          <UnitPhoto id={item.id} photoFileId={item.photoFileId} className="max-h-56 w-full rounded-lg border border-slate-200 object-contain dark:border-slate-700" />
        ) : (
          <p className="rounded-lg border border-dashed border-slate-300 p-3 text-center text-xs text-slate-500 dark:border-slate-600 dark:text-slate-400">
            No photo on file for this unit yet.
          </p>
        )}
        <div>
          <p className="text-lg font-semibold text-slate-900 dark:text-white">{unitTitle(item)}</p>
          {identityLine(item) ? <p className="text-sm text-slate-600 dark:text-slate-400">{identityLine(item)}</p> : null}
          <p className="text-sm text-slate-600 dark:text-slate-400">
            {item.itemCode ?? 'No code'}
            {item.barcode ? ` · ${item.barcode}` : ''}
            {item.size ? ` · Size ${item.size}` : ''}
            {' · '}
            {titleCase(item.condition)}
          </p>
          {item.categoryName ? <p className="text-xs text-slate-500 dark:text-slate-400">{item.categoryName}</p> : null}
          {specs.length > 0 ? (
            <p className="text-xs text-slate-500 dark:text-slate-400">{specs.map(([k, v]) => `${titleCase(k)}: ${v}`).join(' · ')}</p>
          ) : null}
          <p className="mt-1">
            <span className={`rounded-full px-3 py-1 text-xs font-medium ${STATUS_CLASSES[item.status] ?? STATUS_CLASSES.retired}`}>
              {titleCase(item.status)}
            </span>
          </p>
          {data.openLoan ? (
            <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
              Out with {data.openLoan.borrowerName} · {formatPhone(data.openLoan.borrowerPhone)}
              {data.openLoan.expectedReturnAt ? ` · due back ${formatDate(data.openLoan.expectedReturnAt)}` : ''}
            </p>
          ) : null}
          {item.status === 'retired' ? (
            <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
              Out of service{item.retiredReason ? ` - ${REASON_LABELS[item.retiredReason] ?? item.retiredReason}` : ''}
              {item.retiredAt ? `, ${formatDate(item.retiredAt)}` : ''}
            </p>
          ) : null}
        </div>
        {isDispatch ? (
          <div className="grid grid-cols-1 gap-2">
            <button type="button" className={secondaryButtonClass} onClick={onHistory}>
              Unit history
            </button>
            {item.status !== 'retired' ? (
              <button type="button" className={secondaryButtonClass} onClick={onIssue}>
                Report broken or another issue
              </button>
            ) : null}
            {item.status === 'available' ? (
              <button type="button" className={primaryButtonClass} onClick={onLend}>
                Lend out
              </button>
            ) : null}
            {data.openLoan ? (
              <button type="button" className={primaryButtonClass} onClick={onReturn}>
                Mark returned
              </button>
            ) : null}
            <div className="flex items-center justify-between">
              <button type="button" className="text-xs text-slate-500 underline dark:text-slate-400" onClick={onPhoto}>
                {item.photoFileId ? 'Retake photo' : 'Add a photo'}
              </button>
              <button type="button" className="text-xs text-slate-500 underline dark:text-slate-400" onClick={onEdit}>
                Edit details
              </button>
              {item.status === 'maintenance' || item.status === 'available' ? (
                <button type="button" className="text-xs text-slate-500 underline dark:text-slate-400" onClick={onDispose}>
                  Take out of service…
                </button>
              ) : null}
            </div>
          </div>
        ) : null}
      </div>
    </Modal>
  );
}

type ItemFormState = {
  equipmentType: string; name: string; brand: string; model: string; purchaseYear: string; size: string;
  itemCode: string; barcode: string; categoryId: string; condition: string; notes: string; specs: string; reclines: string;
};

const emptyItemForm: ItemFormState = {
  equipmentType: '', name: '', brand: '', model: '', purchaseYear: '', size: '',
  itemCode: '', barcode: '', categoryId: '', condition: 'good', notes: '', specs: '', reclines: '',
};

function formFromRow(row: EquipmentRow): ItemFormState {
  const reclines = row.features?.reclines;
  const specs = row.features?.specs;
  return {
    equipmentType: row.equipmentType,
    name: row.name ?? '',
    brand: row.brand ?? '',
    model: row.model ?? '',
    purchaseYear: row.purchaseYear ? String(row.purchaseYear) : '',
    size: row.size ?? '',
    itemCode: row.itemCode ?? '',
    barcode: row.barcode ?? '',
    categoryId: row.categoryId ?? '',
    condition: row.condition,
    notes: row.notes ?? '',
    specs: typeof specs === 'string' ? specs : '',
    reclines: reclines === true ? 'yes' : reclines === false ? 'no' : '',
  };
}

function formToBody(item: ItemFormState): Record<string, unknown> {
  const isWheelchair = /wheel\s?chair/i.test(item.equipmentType);
  const features: EquipmentFeatures = {};
  if (isWheelchair && item.reclines) features.reclines = item.reclines === 'yes';
  if (item.specs.trim()) features.specs = item.specs.trim();
  return {
    equipmentType: item.equipmentType.trim(),
    name: item.name.trim() || null,
    brand: item.brand.trim() || null,
    model: item.model.trim() || null,
    purchaseYear: item.purchaseYear ? Number(item.purchaseYear) : null,
    size: item.size.trim() || null,
    itemCode: item.itemCode.trim() || null,
    barcode: item.barcode.trim() || null,
    categoryId: item.categoryId || null,
    condition: item.condition,
    notes: item.notes.trim() || null,
    features: Object.keys(features).length ? features : null,
  };
}

