function AddItemModal({
  open, onClose, categories, onSaved,
}: {
  open: boolean;
  onClose: () => void;
  categories: Array<{ id: string; name: string }>;
  onSaved: () => void;
}): React.JSX.Element {
  const [item, setItem] = useState<ItemFormState>(emptyItemForm);

  const createItem = useMutation({
    mutationFn: () => api.post('/api/equipment', formToBody(item)),
    onSuccess: () => {
      onSaved();
      toast.success('Item added.');
      onClose();
      setItem(emptyItemForm);
    },
    onError: (error: unknown) => toast.error(errorMessage(error)),
  });

  return (
    <Modal open={open} title="Add an item" onClose={onClose}>
      <form
        className="space-y-4"
        onSubmit={(event) => {
          event.preventDefault();
          const parsed = equipmentSchema.safeParse(formToBody(item));
          if (!parsed.success) {
            toast.error(parsed.error.issues[0]?.message ?? 'Check the details above.');
            return;
          }
          createItem.mutate();
        }}
      >
        <ItemFields item={item} setItem={setItem} categories={categories} idPrefix="equipment" showItemCode />
        <div className="flex gap-2">
          <button type="submit" className={primaryButtonClass} disabled={createItem.isPending}>
            Save item
          </button>
          <button type="button" className={secondaryButtonClass} onClick={onClose}>
            Cancel
          </button>
        </div>
      </form>
    </Modal>
  );
}

function EditItemModal({ row, categories, onClose, onSaved }: {
  row: EquipmentRow;
  categories: Array<{ id: string; name: string }>;
  onClose: () => void;
  onSaved: () => void;
}): React.JSX.Element {
  const [item, setItem] = useState<ItemFormState>(() => formFromRow(row));

  const saveItem = useMutation({
    mutationFn: () => {
      // Send only what changed so the audit entry stays meaningful.
      const next = formToBody(item);
      delete next.itemCode; // identity; not editable
      const body: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(next)) {
        const prev = key === 'features' ? row.features ?? null : (row as unknown as Record<string, unknown>)[key] ?? null;
        if (JSON.stringify(value ?? null) !== JSON.stringify(prev)) body[key] = value;
      }
      return api.patch(`/api/equipment/${row.id}`, body);
    },
    onSuccess: () => {
      onSaved();
      toast.success('Item updated.');
      onClose();
    },
    onError: (error: unknown) => toast.error(errorMessage(error)),
  });

  return (
    <Modal open title={`Edit - ${unitTitle(row)}`} onClose={onClose}>
      <form
        className="space-y-4"
        onSubmit={(event) => {
          event.preventDefault();
          saveItem.mutate();
        }}
      >
        <p className="text-sm text-slate-500 dark:text-slate-400">
          Item code {row.itemCode ?? 'not set'} stays the same. Every change is recorded in the unit's history.
        </p>
        <ItemFields item={item} setItem={setItem} categories={categories} idPrefix="edit-equipment" showItemCode={false} />
        <div className="flex gap-2">
          <button type="submit" className={primaryButtonClass} disabled={saveItem.isPending}>
            Save changes
          </button>
          <button type="button" className={secondaryButtonClass} onClick={onClose}>
            Cancel
          </button>
        </div>
      </form>
    </Modal>
  );
}

