/**
 * F-10: invite/reset tokens arrive in the query string. Left there, they sit
 * in browser history on a shared device (and in any copied link). The pages
 * read the token into state on mount, then strip it from the address bar.
 */
export function stripQueryParamFromUrl(param: string): void {
  if (typeof window === 'undefined') return;
  const url = new URL(window.location.href);
  if (!url.searchParams.has(param)) return;
  url.searchParams.delete(param);
  const search = url.searchParams.size > 0 ? `?${url.searchParams.toString()}` : '';
  window.history.replaceState(null, '', `${url.pathname}${search}${url.hash}`);
}
