/** Browser-only equipment simulation. No network, real records or sends.
 * State resets on reload, as the demo ribbon says. */
import type { EquipmentRow, EquipmentLoanRow, EquipmentHistoryEvent } from '../../types/api';
import { equipmentSchema, equipmentUpdateSchema, loanEquipmentSchema } from '@rvc/shared';

let units: EquipmentRow[] = [];
let loans: EquipmentLoanRow[] = [];
const events = new Map<string, EquipmentHistoryEvent[]>();
const photos = new Map<string, string>();
export function initEquipment(rows: EquipmentRow[], loanRows: EquipmentLoanRow[]): void {
  units = structuredClone(rows).map((r) => Object.assign({ name: null, brand: null, model: null, purchaseYear: null, size: null, features: null, photoFileId: null, retiredAt: null, retiredReason: null }, r));
  loans = structuredClone(loanRows);
}
export function demoUnitPhoto(id: string): string | undefined { return photos.get(id); }
function event(id: string, action: string, metadata: Record<string, unknown> = {}, next?: Record<string, unknown>): void {
  events.set(id, [{ id: crypto.randomUUID(), action, actorName: 'Demo administrator', at: new Date().toISOString(), metadata, next }, ...(events.get(id) ?? [])]);
}
function fail(message: string): never { throw Object.assign(new Error(message), { status: 409 }); }
function label(r: EquipmentRow): string { return `RVC${(r.itemCode ?? '').replace(/[^A-Za-z0-9]/g, '').toUpperCase().slice(0, 12)}`; }
export function equipmentDemoRequest(method: string, fullPath: string, body?: unknown): { handled: boolean; data?: unknown } {
  const [path = '', query = ''] = fullPath.split('?');
  const b = (body ?? {}) as Record<string, unknown>;
  const out = (data: unknown) => ({ handled: true, data: structuredClone(data) });
  const open = (id: string) => loans.find((l) => l.equipmentId === id && !l.returnedAt) ?? null;
  const disposal = () => {
    const counts = new Map<string, { equipmentType: string; reason: string | null; count: number }>();
    for (const u of units.filter((u) => u.status === 'retired')) {
      const key = `${u.equipmentType}:${u.retiredReason}`;
      const entry = counts.get(key) ?? { equipmentType: u.equipmentType, reason: u.retiredReason, count: 0 };
      entry.count++; counts.set(key, entry);
    }
    return [...counts.values()];
  };
  if (path === '/api/equipment' && method === 'GET') return out({ equipment: [...units].sort((a,b) => a.equipmentType.localeCompare(b.equipmentType) || (a.itemCode ?? '').localeCompare(b.itemCode ?? '')) });
  if (path === '/api/equipment/loans' && method === 'GET') return out({ loans: new URLSearchParams(query).get('open') === 'false' ? loans : loans.filter((l) => !l.returnedAt) });
  if (path === '/api/equipment/disposal-report' && method === 'GET') return out({ report: disposal() });
  if (path === '/api/reports/equipment' && method === 'GET') {
    const byStatus: Record<string, number> = {};
    units.forEach((u) => { byStatus[u.status] = (byStatus[u.status] ?? 0) + 1; });
    return out({ byStatus, overdue: loans.filter((l) => !l.returnedAt && l.expectedReturnAt && Date.parse(l.expectedReturnAt) < Date.now()).map((l) => ({ itemCode: l.itemCode, type: l.equipmentType, borrower: l.borrowerName, daysOverdue: Math.floor((Date.now() - Date.parse(l.expectedReturnAt!)) / 86400000) })) });
  }
  if (path.startsWith('/api/equipment/scan/') && method === 'GET') {
    const code = decodeURIComponent(path.slice('/api/equipment/scan/'.length)).toLowerCase();
    const u = units.find((r) => [r.itemCode, r.barcode, label(r)].some((v) => v?.toLowerCase() === code));
    if (!u) throw Object.assign(new Error('No equipment matches that code.'), { status: 404 });
    return out({ item: { ...u, categoryName: null }, openLoan: open(u.id) });
  }
  if (path === '/api/equipment' && method === 'POST') {
    const data = equipmentSchema.parse(body);
    if (units.some((u) => (data.itemCode && u.itemCode === data.itemCode) || (data.barcode && u.barcode === data.barcode))) fail('That item code or barcode is already in use.');
    const u: EquipmentRow = { id: crypto.randomUUID(), categoryId: null, itemCode: null, barcode: null, name: null, brand: null, model: null, purchaseYear: null, size: null, features: null, photoFileId: null, retiredAt: null, retiredReason: null, notes: null, createdAt: new Date().toISOString(), status: 'available', ...data };
    units.push(u); event(u.id, 'equipment.created'); return out({ equipment: u });
  }
  const match = path.match(/^\/api\/equipment\/([^/]+)(?:\/(history|photo|loan|return|issue|decommission))?$/);
  if (!match) return { handled: false };
  const [, id = '', action] = match;
  const u = units.find((r) => r.id === id);
  if (!u) throw Object.assign(new Error('Equipment not found.'), { status: 404 });
  if (method === 'GET' && action === 'history') return out({ item: u, loans: loans.filter((l) => l.equipmentId === id), events: events.get(id) ?? [{ id: crypto.randomUUID(), action: 'equipment.created', actorName: 'Demo administrator', at: u.createdAt, metadata: null }] });
  if (method === 'PATCH' && !action) {
    const data = equipmentUpdateSchema.parse(body);
    Object.assign(u, data); event(id, 'equipment.updated', {}, data); return out({ equipment: u });
  }
  if (method !== 'POST') return { handled: false };
  if (action === 'photo') {
    const image = String(b.image ?? '');
    if (!/^data:image\/(png|jpeg|webp|gif);base64,/.test(image) || image.length > 11200000) fail('Use an image under 8 MB.');
    const previousFileId = u.photoFileId;
    u.photoFileId = crypto.randomUUID(); photos.set(id, image);
    event(id, 'equipment.photo_updated', { fileId: u.photoFileId, previousFileId }); return out({ photoFileId: u.photoFileId });
  }
  if (action === 'loan') {
    if (u.status !== 'available' || open(id)) fail(`That item is ${u.status}.`);
    const data = loanEquipmentSchema.parse(body);
    const loan: EquipmentLoanRow = { id: crypto.randomUUID(), equipmentId: id, itemCode: u.itemCode, equipmentType: u.equipmentType, borrowerName: data.borrowerName, borrowerPhone: data.borrowerPhone, expectedReturnAt: data.expectedReturnAt?.toISOString() ?? null, returnedAt: null, loanedAt: new Date().toISOString(), ...{ notes: data.notes ?? null } };
    loans.unshift(loan); u.status = 'loaned'; event(id, 'equipment.loaned'); return out({ loan });
  }
  if (action === 'return') {
    const l = open(id); if (!l) fail('That item is not currently on loan.');
    l.returnedAt = new Date().toISOString(); Object.assign(l, { notes: b.notes ?? null });
    u.status = 'available'; if (b.condition) u.condition = String(b.condition); event(id, 'equipment.returned'); return out({ ok: true });
  }
  if (action === 'issue') {
    if (b.kind !== 'other' && (u.status === 'retired' || u.status === 'loaned')) fail(`That unit is ${u.status}; its status cannot change here.`);
    const kind = String(b.kind); const previousCondition = u.condition;
    if (!['broken', 'other', 'resolved'].includes(kind) || !String(b.note ?? '').trim()) fail('Choose an issue and add a note.');
    if (kind === 'resolved' && u.status !== 'maintenance') fail('Only a unit in maintenance can return to service.');
    if (kind !== 'other') { u.status = kind === 'broken' ? 'maintenance' : 'available'; u.condition = String(b.condition ?? (kind === 'broken' ? 'damaged' : 'good')); }
    event(id, kind === 'resolved' ? 'equipment.issue_resolved' : 'equipment.issue_reported', { ...b, previousCondition }); return out({ equipment: u });
  }
  if (action === 'decommission') {
    if (!['available', 'maintenance'].includes(u.status)) fail(`That unit is ${u.status}.`);
    if (String(b.note ?? '').trim().length < 2) fail('Add a note.');
    if (!['beyond_repair', 'lost', 'worn_out', 'other'].includes(String(b.reason))) fail('Choose a disposition reason.');
    u.status = 'retired'; u.retiredAt = new Date().toISOString(); u.retiredReason = String(b.reason);
    event(id, 'equipment.decommissioned', b); return out({ equipment: u });
  }
  return { handled: false };
}
