/**
 * Camera barcode scanning.
 *
 * Uses the native BarcodeDetector (Chrome / Edge, including Chrome for
 * Android). It does not exist in Safari or Firefox, and even on Chrome its
 * availability varies by device, so this component is strictly an
 * enhancement: when the API, the camera, or permission is missing it says so
 * plainly and the caller's manual entry stays the way in. The scan itself
 * never changes anything - it only fills in a code.
 */
import React, { useEffect, useRef, useState } from 'react';
import { CameraOff } from 'lucide-react';

export function BarcodeScanner({ onDetected }: { onDetected: (code: string) => void }): React.JSX.Element {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [problem, setProblem] = useState<string | null>(null);
  const [live, setLive] = useState(false);

  useEffect(() => {
    if (!('BarcodeDetector' in window)) {
      setProblem('This browser cannot scan barcodes with the camera. Type the code below instead.');
      return;
    }
    let stopped = false;
    let stream: MediaStream | null = null;
    let raf = 0;

    const start = async (): Promise<void> => {
      try {
        const detector = new BarcodeDetector({ formats: ['code_128', 'code_39', 'ean_13', 'qr_code'] });
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' }, audio: false });
        if (stopped) {
          stream.getTracks().forEach((track) => track.stop());
          return;
        }
        const video = videoRef.current;
        if (!video) return;
        video.srcObject = stream;
        await video.play();
        setLive(true);
        const tick = async (): Promise<void> => {
          if (stopped) return;
          try {
            const codes = await detector.detect(video);
            const hit = codes.find((code) => code.rawValue.trim().length > 0);
            if (hit) {
              stopped = true;
              stream?.getTracks().forEach((track) => track.stop());
              onDetected(hit.rawValue.trim());
              return;
            }
          } catch {
            /* a frame that cannot be decoded is normal while aiming */
          }
          raf = requestAnimationFrame(() => void tick());
        };
        void tick();
      } catch (err) {
        if (stopped) return;
        const denied = err instanceof DOMException && (err.name === 'NotAllowedError' || err.name === 'SecurityError');
        setProblem(
          denied
            ? 'Camera permission was not granted. Type the code below instead, or allow the camera and try again.'
            : 'The camera could not be started. Type the code below instead.',
        );
      }
    };
    void start();

    return () => {
      stopped = true;
      cancelAnimationFrame(raf);
      stream?.getTracks().forEach((track) => track.stop());
    };
  }, [onDetected]);

  if (problem) {
    return (
      <div className="flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm text-slate-600 dark:border-slate-700 dark:bg-slate-800/60 dark:text-slate-300">
        <CameraOff className="h-4 w-4 shrink-0" aria-hidden="true" />
        <p>{problem}</p>
      </div>
    );
  }

  return (
    <div className="overflow-hidden rounded-lg border border-slate-200 dark:border-slate-700">
      <video ref={videoRef} className="aspect-[4/3] w-full bg-black object-cover" muted playsInline aria-label="Camera view for scanning a barcode" />
      <p className="bg-slate-50 px-3 py-2 text-center text-xs text-slate-500 dark:bg-slate-800/60 dark:text-slate-400">
        {live ? 'Point the camera at the barcode on the unit.' : 'Starting the camera…'}
      </p>
    </div>
  );
}
