/**
 * One-tap hubs that keep the main menu short: More, Admin and My profile.
 * Each lists the screens of its section for the signed-in person.
 */
import React from 'react';
import { Link } from 'react-router-dom';
import { ChevronRight } from 'lucide-react';
import { useAuth } from '@/lib/auth';
import { useFeatures } from '@/lib/features';
import { sectionItems, type NavSection } from '@/components/Layout';
import { PageHeader, cardClass } from '@/components/states';
import { navLabel, useI18n, type MessageKey } from '@/i18n';

const TITLES: Record<Exclude<NavSection, 'main'>, { title: MessageKey; subtitle: MessageKey }> = {
  more: { title: 'hub.more.title', subtitle: 'hub.more.subtitle' },
  admin: { title: 'hub.admin.title', subtitle: 'hub.admin.subtitle' },
  profile: { title: 'hub.profile.title', subtitle: 'hub.profile.subtitle' },
};

/** Admin hub grouping: related screens sit side by side (two columns from
 *  small screens up, one on a phone) under a short heading. Order within a
 *  group follows the menu order; anything not listed lands under Other, so
 *  future admin screens appear without touching this page. Layout only -
 *  same routes, same items, same permissions. */
const ADMIN_GROUPS: Array<{ key: MessageKey; match: (to: string) => boolean }> = [
  { key: 'hub.admin.group.people', match: (to) => ['/admin/people', '/admin/departments', '/admin/cards'].includes(to) },
  { key: 'hub.admin.group.messages', match: (to) => ['/admin/notifications', '/email-builder', '/admin/templates'].includes(to) },
  { key: 'hub.admin.group.reports', match: (to) => ['/impact', '/reports'].includes(to) },
  { key: 'hub.admin.group.data', match: (to) => ['/admin/backup', '/admin/exports', '/admin/audit', '/admin/data-fixes'].includes(to) },
  { key: 'hub.admin.group.settings', match: (to) => to === '/admin/settings' },
];

export function HubPage({ section }: { section: Exclude<NavSection, 'main'> }): React.JSX.Element {
  const { user } = useAuth();
  const features = useFeatures(Boolean(user));
  const role = user?.role ?? 'volunteer';
  const items = sectionItems(role, user?.navHidden, section, features);
  const { t } = useI18n();
  const title = t(TITLES[section].title);
  const subtitle = t(TITLES[section].subtitle);
  return (
    <div className="space-y-4">
      <PageHeader title={title} subtitle={subtitle} />
      {section === 'admin' ? (
        <GroupedAdminItems items={items} />
      ) : (
        <ul className="space-y-2">
          {items.map((item) => (
            <HubLink key={item.to} item={item} />
          ))}
        </ul>
      )}
      {section === 'more' ? (
        <p className="pt-2 text-center text-sm text-slate-500 dark:text-slate-400">
          <Link to="/privacy" className="underline">Privacy notice</Link>
        </p>
      ) : null}
    </div>
  );
}

function HubLink({ item }: { item: ReturnType<typeof sectionItems>[number] }): React.JSX.Element {
  const { t } = useI18n();
  const Icon = item.icon;
  return (
    <li>
      <Link
        to={item.to}
        className={`${cardClass} flex min-h-[56px] items-center gap-3 p-4 hover:bg-slate-50 dark:hover:bg-slate-800`}
      >
        <Icon className="h-5 w-5 flex-shrink-0 text-[#C80023] dark:text-red-400" />
        <span className="min-w-0 flex-1">
          <span className="block font-medium text-slate-900 dark:text-white">{navLabel(t, item.to, item.label)}</span>
          {item.hint ? (
            <span className="block text-sm text-slate-500 dark:text-slate-400">{item.hint}</span>
          ) : null}
        </span>
        <ChevronRight className="h-5 w-5 text-slate-500 dark:text-slate-400" aria-hidden="true" />
      </Link>
    </li>
  );
}

function GroupedAdminItems({ items }: { items: ReturnType<typeof sectionItems> }): React.JSX.Element {
  const { t } = useI18n();
  const grouped: Array<{ key: MessageKey; items: typeof items }> = [];
  for (const group of ADMIN_GROUPS) {
    const inGroup = items.filter((item) => group.match(item.to));
    if (inGroup.length > 0) grouped.push({ key: group.key, items: inGroup });
  }
  const matched = new Set(ADMIN_GROUPS.flatMap((group) => items.filter((item) => group.match(item.to)).map((item) => item.to)));
  const rest = items.filter((item) => !matched.has(item.to));
  if (rest.length > 0) grouped.push({ key: 'hub.admin.group.other', items: rest });
  return (
    <div className="space-y-5">
      {grouped.map((group) => (
        <section key={group.key}>
          <h2 className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">
            {t(group.key)}
          </h2>
          <ul className="grid grid-cols-1 gap-2 sm:grid-cols-2">
            {group.items.map((item) => (
              <HubLink key={item.to} item={item} />
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
}
